  ('ict-lec-ch02-mcq-356', 'class9-ict-bn-guide', 'ict-lecture-satt', 'যন্ত্র কখন ধীর হয়ে যায়? (Ávb) রেখে দেওয়া মুছে দেওয়া', 'mcq', '{"ক":"তথ্য ও যোগাযোগ প্রযুক্তি","খ":"Aa¨vqwfwËK বহুনিবার্চনি প্রশ্নের উত্তর","গ":"(Ávb)","ঘ":"(Abyaveb)"}'::jsonb, 'গ', null, 1, null, 'mcq_bank', null, 2, false),
