  ('ict-lec-ch03-mcq-291', 'class9-ict-bn-guide', 'ict-lecture-satt', 'অডিও কনটেন্টের অন্ত্মভুর্ক্ত হলো হাডর্ওয়্যার বিষয়ে পড়াচ্ছিলেন। একপযাের্য় তিনি i. ওয়েবিনারো পাওয়ার পয়েন্ট ব্যবহার করে শিÿাথীের্দরকে বোঝাতে শুরম্ন ii. ইনফো-গ্রাফিক্স করলেন।', 'mcq', '{"ক":"I I I I msKi gva¨g MYgva¨g","খ":"iii","গ":"ii iii","ঘ":"i, ii iii"}'::jsonb, 'খ', null, 1, null, 'mcq_bank', null, 3, false),
