  ('ict-lec-ch04-mcq-089', 'class9-ict-bn-guide', 'ict-lecture-satt', 'ওয়াডর্ প্রসেসরে ডকুমেন্ট প্রিন্টের কীবোডর্ কমান্ড কোনটি? (জ্ঞান) এক বার দুই বার ক খ', 'mcq', '{"ক":"Shift + P","খ":"Alt + P","গ":"নবম-দশম শ্রেণি : তথ্য ও যোগাযোগ প্রযুক্তি ৯৭","ঘ":"P + enter"}'::jsonb, 'গ', null, 1, null, 'mcq_bank', null, 4, false),
  ('ict-lec-ch04-mcq-115', 'class9-ict-bn-guide', 'ict-lecture-satt', 'রাজন তার কম্পিউটারে ওয়াডর্ ২০০৭ চালু করল। কিছুক্ষণ পর তার মনিটরের i. পুরো লেখাকে মুছে ফেলা যায় পদার্য় একটি উইণ্ডো দেখা গেল। এই উইণ্ডোতে', 'mcq', '{"ক":"ii","খ":"iii নিচের কোনটি সঠিক? (প্রয়োগ) ii ওiii i, ii ওiii","গ":"i ওii i ওiii","ঘ":"i, ii iii i. স্পেল চেকারের সাহায্যে"}'::jsonb, 'গ', null, 1, null, 'mcq_bank', null, 4, false),
